#include <bits/stdc++.h>
using namespace std;

struct ListNode {
  int val;
  ListNode *next;
  ListNode() : val(0), next(nullptr) {}
  ListNode(int x) : val(x), next(nullptr) {}
  ListNode(int x, ListNode *next) : val(x), next(next) {}
};

void printVec(std::vector<int> &answer) {
  std::cout << "[";
  for (auto a : answer) {
    std::cout << a << ", ";
  }
  std::cout << "\b\b]" << std::endl;
}

class Solution {
private:
  [[nodiscard]] constexpr bool isLocalExtremum(int prevVal, int currVal,
                                               int nextVal) const noexcept {
    return (currVal > prevVal && currVal > nextVal) ||
           (currVal < prevVal && currVal < nextVal);
  }

public:
  std::vector<int> nodesBetweenCriticalPoints(const ListNode *head) {
    if (head == nullptr || head->next == nullptr ||
        head->next->next == nullptr) {
      return {-1, -1};
    }

    const ListNode *prev = head;
    const ListNode *curr = head->next;
    const ListNode *next = curr->next;

    int minDistance = -1;
    int maxDistance = -1;
    int firstIdx = -1;
    int prevIdx = -1;
    int idx = 2;

    while (next != nullptr) {
      if (isLocalExtremum(prev->val, curr->val, next->val)) {
        if (firstIdx == -1) {
          firstIdx = idx;
        } else {
          int distance = idx - prevIdx;
          minDistance =
              (minDistance == -1) ? distance : std::min(minDistance, distance);
        }
        prevIdx = idx;
      }

      prev = curr;
      curr = next;
      next = next->next;
      ++idx;
    }

    if (firstIdx != prevIdx) {
      maxDistance = prevIdx - firstIdx;
    }

    return {minDistance, maxDistance};
  }
};

